package cl.duoc.bancoxyz.customers.event;
import cl.duoc.bancoxyz.customers.model.SecurityAlert; import cl.duoc.bancoxyz.customers.repository.SecurityAlertRepository; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(name="app.kafka.enabled",havingValue="true") public class SecurityAlertConsumer {private final ObjectMapper mapper;private final SecurityAlertRepository repository;public SecurityAlertConsumer(ObjectMapper mapper,SecurityAlertRepository repository){this.mapper=mapper;this.repository=repository;}@KafkaListener(topics="alertas.seguridad",groupId="customer-service") public void consume(String json)throws Exception{SecurityAlertEvent e=mapper.readValue(json,SecurityAlertEvent.class);if(!repository.existsById(e.eventId()))repository.save(new SecurityAlert(e.eventId(),e.operationId(),e.customerId(),e.amount(),e.reason(),e.occurredAt()));}}
